/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en" data-theme="light">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Notification settings · Team chat</title>
  <style>
    :root {
      color-scheme: light;
      --ink: #232236;
      --muted: #625e73;
      --line: #ebe8f0;
      --accent: #6543aa;
      --lobe-color-primary: var(--accent);
      font: 14px/1.5 system-ui, sans-serif;
      color: var(--ink);
      background: #f8f7fb;
    }
    * { box-sizing: border-box; }
    body { margin: 0; }
    .topbar { border-bottom: 1px solid var(--line); background: #fff; }
    .topbar-inner {
      max-width: 1120px;
      margin: auto;
      min-height: 64px;
      display: flex;
      align-items: center;
      gap: 11px;
      padding: 0 24px;
      font-weight: 650;
    }
    .app-icon, .section-icon {
      display: grid;
      place-items: center;
      flex: none;
      color: var(--accent);
      background: #f1ebfc;
    }
    .app-icon { width: 32px; height: 32px; border-radius: 9px; }
    .section-icon { width: 38px; height: 38px; border-radius: 10px; }
    .breadcrumb { display: flex; align-items: center; gap: 9px; color: var(--muted); font-weight: 450; }
    main { max-width: 752px; margin: 0 auto; padding: 48px 24px 64px; }
    .intro { margin-bottom: 26px; }
    h1, h2, p { margin: 0; }
    h1 { font-size: clamp(30px, 6vw, 40px); line-height: 1.12; letter-spacing: -.045em; }
    .intro p { margin-top: 10px; font-size: 15px; }
    p { color: var(--muted); }
    ryugi-card {
      display: block;
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 16px;
    }
    .settings { padding: 0 25px; }
    .section { padding: 22px 0; }
    .section + .section, .actions { border-top: 1px solid var(--line); }
    .section-header { display: flex; gap: 13px; align-items: flex-start; }
    h2 { font-size: 16px; line-height: 1.4; letter-spacing: -.015em; }
    .section-header p { margin-top: 3px; font-size: 13px; }
    .section-title { flex: 1; }
    .section-header ryugi-switch { margin-top: 5px; flex: none; }
    .fields { margin: 16px 0 0 51px; }
    .field { display: grid; gap: 6px; min-width: 0; }
    .field-name { font-size: 13px; font-weight: 650; }
    #digest-frequency { display: block; width: min(100%, 240px); }
    #muted-channels { display: block; width: 100%; }
    .time-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; max-width: 360px; }
    input[type="time"] {
      width: 100%;
      min-width: 0;
      min-height: 36px;
      padding: 5px 9px;
      font: inherit;
      color: var(--ink);
      background: #fff;
      border: 1px solid #dcd8e4;
      border-radius: 8px;
    }
    input[type="time"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .actions { display: flex; justify-content: flex-end; padding: 18px 0; }
    @media (max-width: 460px) {
      main { padding: 32px 16px 44px; }
      .topbar-inner { padding: 0 16px; }
      .settings { padding: 0 16px; }
      .fields { margin-left: 0; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="topbar-inner">
      <span class="app-icon"><ryugi-icon name="message-square" size="17"></ryugi-icon></span>
      <span>Team chat</span>
      <span class="breadcrumb"><ryugi-icon name="chevron-right" size="14"></ryugi-icon> Settings</span>
    </div>
  </header>
  <main>
    <div class="intro">
      <h1>Notifications</h1>
      <p>Choose what reaches you and when.</p>
    </div>

    <ryugi-card variant="borderless">
      <form class="settings" id="notification-settings">
        <section class="section" aria-labelledby="digest-title">
          <div class="section-header">
            <span class="section-icon"><ryugi-icon name="mail" size="18"></ryugi-icon></span>
            <div class="section-title">
              <h2 id="digest-title">Email digest</h2>
              <p>Get a summary of unread messages by email.</p>
            </div>
            <ryugi-switch id="email-digest" aria-label="Email digest" checked></ryugi-switch>
          </div>
          <div class="fields field">
            <span class="field-name" id="frequency-label">Frequency</span>
            <ryugi-select id="digest-frequency" aria-labelledby="frequency-label" value="daily">
              <ryugi-option value="daily">Daily</ryugi-option>
              <ryugi-option value="weekly">Weekly</ryugi-option>
              <ryugi-option value="monthly">Monthly</ryugi-option>
            </ryugi-select>
          </div>
        </section>

        <section class="section" aria-labelledby="channels-title">
          <div class="section-header">
            <span class="section-icon"><ryugi-icon name="bell-off" size="18"></ryugi-icon></span>
            <div class="section-title">
              <h2 id="channels-title">Muted channels</h2>
              <p>Pause notifications from the channels you select.</p>
            </div>
          </div>
          <div class="fields">
            <ryugi-select id="muted-channels" aria-labelledby="channels-title" mode="multiple" placeholder="Select channels" showSearch allowClear>
              <ryugi-option value="general">#general</ryugi-option>
              <ryugi-option value="announcements">#announcements</ryugi-option>
              <ryugi-option value="design">#design</ryugi-option>
              <ryugi-option value="engineering">#engineering</ryugi-option>
              <ryugi-option value="product">#product</ryugi-option>
              <ryugi-option value="random">#random</ryugi-option>
            </ryugi-select>
          </div>
        </section>

        <section class="section" aria-labelledby="quiet-title">
          <div class="section-header">
            <span class="section-icon"><ryugi-icon name="moon" size="18"></ryugi-icon></span>
            <div class="section-title">
              <h2 id="quiet-title">Quiet hours</h2>
              <p>Pause chat notifications every day during this window, in your local time.</p>
            </div>
          </div>
          <div class="fields time-fields">
            <label class="field" for="quiet-start">
              <span class="field-name">Start time</span>
              <input id="quiet-start" type="time" value="22:00" required>
            </label>
            <label class="field" for="quiet-end">
              <span class="field-name">End time</span>
              <input id="quiet-end" type="time" value="08:00" required>
            </label>
          </div>
        </section>

        <div class="actions">
          <ryugi-button id="save-settings" variant="filled" type="button">Save changes</ryugi-button>
        </div>
      </form>
    </ryugi-card>
  </main>
  <script>
    document.addEventListener('"'ryugi-ui:ready', () => {
      const form = document.getElementById('notification-settings');
      const digest = document.getElementById('email-digest');
      const frequency = document.getElementById('digest-frequency');
      const channels = document.getElementById('muted-channels');
      const start = document.getElementById('quiet-start');
      const end = document.getElementById('quiet-end');
      const save = document.getElementById('save-settings');

      function renderDigest() {
        frequency.toggleAttribute('disabled', "'!digest.checked);
      }

      function saveSettings() {
        if (!form.reportValidity()) return;
        form.dataset.savedSettings = JSON.stringify({
          emailDigest: digest.checked,
          digestFrequency: frequency.value,
          mutedChannels: channels.value ?? [],
          quietStart: start.value,
          quietEnd: end.value,
        });
        window.ryugiToast.success({ id: '"'notification-save', title: 'Notification settings saved' });
      }

      digest.addEventListener('ryugi-change', renderDigest);
      save.addEventListener('click', saveSettings);
      form.addEventListener('submit', (event) => {
        event.preventDefault();
        saveSettings();
      });
      renderDigest();
    }, { once: true });
  </script>
</body>
</html>
EOF"

